int x = 3;
x = x + 2;
// x is now 5, not 3.
System.out.println(x); // displays 5

int total = 0;
for (int i = 1; i <= 3; i++) { total = total + i; }
// totals: 0 → 1 → 3 → 6

int[] a = {2, 5};
int total = 0;
for (int i = 0; i < a.length; i++) { total += a[i]; }
// total: 0 → 2 → 7

int count = 0;
for (int i = 0; i < a.length; i++) { if (a[i] > 0) { count++; } }
// [2,-1,2] has 2 positive values.

int best = a[0];
for (int i = 1; i < a.length; i++) { if (a[i] > best) { best = a[i]; } }
// [-5,-2,-7]: best goes -5 → -2 → -2

String s = "cat";
// s.length() is 3; s.charAt(1) is 'a'.
// "hi".equals("hi") compares string contents.

StringBuilder out = new StringBuilder();
out.append('b'); out.append('a');
// out.toString() is "ba".

String a = new String("hi");
String b = new String("hi");
// a.equals(b) is true, even though a and b are different objects.

List<Integer> out = new ArrayList<>();
out.add(4); out.add(7);
// out.get(0) is 4; out.size() is 2.

int[] counts = new int[10];
for (int x : a) { counts[x]++; }
// [2,2,5]: counts[2] = 2; counts[5] = 1. The for-each loop visits values directly.

HashSet<Integer> seen = new HashSet<>();
seen.add(5); seen.add(5);
// seen.size() is 1; seen.contains(5) is true.

HashMap<Integer,Integer> counts = new HashMap<>();
counts.put(7, counts.getOrDefault(7, 0) + 1);
// key 7 now has count 1.

ArrayDeque<Integer> stack = new ArrayDeque<>();
stack.push(2); stack.push(5);
// stack.pop() returns 5.

ArrayDeque<Integer> queue = new ArrayDeque<>();
queue.addLast(2); queue.addLast(5);
// queue.removeFirst() returns 2.

class Node { int value; Node next; Node(int v) { value = v; } }
Node a = new Node(2); a.next = new Node(5);
// a.next.value is 5.

PriorityQueue<Integer> heap = new PriorityQueue<>(Comparator.reverseOrder());
heap.add(2); heap.add(7);
// heap.poll() returns 7. Import java.util.PriorityQueue and java.util.Comparator.

